import { readFileSync, mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const projectRoot = dirname(dirname(fileURLToPath(import.meta.url)));
const distDir = join(projectRoot, "dist");

const dataJs = readFileSync(join(projectRoot, "src", "data.js"), "utf8").replace(
  "export const applications =",
  "const sampleApplications ="
);
const domainJs = stripExports(readFileSync(join(projectRoot, "src", "domain.js"), "utf8"));
const storageJs = stripExports(readFileSync(join(projectRoot, "src", "storage.js"), "utf8"));
const appJs = stripImports(readFileSync(join(projectRoot, "src", "app.js"), "utf8"));

mkdirSync(distDir, { recursive: true });
writeFileSync(
  join(distDir, "app.bundle.js"),
  [
    "/*",
    "  Generated by scripts/build-browser-bundle.mjs.",
    "  Edit src/*.js, then rebuild this file.",
    "*/",
    dataJs,
    domainJs,
    storageJs,
    appJs
  ].join("\n\n")
);

function stripExports(source) {
  return source.replace(/^export /gm, "");
}

function stripImports(source) {
  return source.replace(/import[\s\S]*?from "\.\/(?:data|domain|storage)\.js";\r?\n/g, "");
}
